-- Curate the platform-managed default chicken Breed Library.
--
-- Scope:
-- - Preserve every existing stable breed ID and slug.
-- - Deactivate 28 superseded/default-library records; do not delete them.
-- - Refresh approved metadata for the 206 surviving records.
-- - Add 11 approved chicken records with new stable IDs/slugs.
-- - Do not touch seller_breed_profiles, listings, media, or storefront views.

create temporary table _chicken_catalog_plan (
  source_id uuid not null,
  breed_slug text primary key,
  expected_breed_name text not null,
  target_breed_name text not null,
  is_active boolean not null,
  category text,
  description text,
  bird_type text,
  egg_color text,
  annual_egg_production text,
  temperament text,
  required boolean not null
) on commit drop;

insert into _chicken_catalog_plan (
