    ('128adfad-ef27-4c95-a0f5-8c63f48714d5', 'ameraucana-brown-red', 'Ameraucana - Brown Red', 'Layers', 'Ameraucana chickens originated in United States and were developed during 1970s. They were standardized from bearded, muffed, tailed blue-egg-laying stock. Their history reflects the practical and cultural priorities of the farmers and breeders who maintained them before modern poultry production narrowed the number of commonly used breeds.

Ameraucana chickens have a pea comb, slate legs, beard, muffs, and a full tail. FlockFront classifies this profile as Layers. Hens lay medium blue eggs, typically 150–200 eggs per year. They are generally alert. They forage capably, and their facial feathering should be checked for moisture, debris, and parasites. Egg output varies with age, season, nutrition, lighting, health, and management, so the production figure is a practical breed range rather than a guarantee.', 'layer', 'blue', '150_200', 'Alert', 2410),
    ('56aabdcd-6a85-4607-bcb7-581e405048d1', 'ameraucana-silver', 'Ameraucana - Silver', 'Layers', 'Ameraucana chickens originated in United States and were developed during 1970s. They were standardized from bearded, muffed, tailed blue-egg-laying stock. Their history reflects the practical and cultural priorities of the farmers and breeders who maintained them before modern poultry production narrowed the number of commonly used breeds.

Ameraucana chickens have a pea comb, slate legs, beard, muffs, and a full tail. FlockFront classifies this profile as Layers. Hens lay medium blue eggs, typically 150–200 eggs per year. They are generally alert. They forage capably, and their facial feathering should be checked for moisture, debris, and parasites. Egg output varies with age, season, nutrition, lighting, health, and management, so the production figure is a practical breed range rather than a guarantee.', 'layer', 'blue', '150_200', 'Alert', 2420),
    ('468fe2d6-a2a8-4322-9f43-daaf875e7781', 'ameraucana-ermine', 'Ameraucana - Ermine', 'Layers', 'Ameraucana chickens originated in United States and were developed during 1970s. They were standardized from bearded, muffed, tailed blue-egg-laying stock. Their history reflects the practical and cultural priorities of the farmers and breeders who maintained them before modern poultry production narrowed the number of commonly used breeds.

Ameraucana chickens have a pea comb, slate legs, beard, muffs, and a full tail. FlockFront classifies this profile as Layers. Hens lay medium blue eggs, typically 150–200 eggs per year. They are generally alert. They forage capably, and their facial feathering should be checked for moisture, debris, and parasites. Egg output varies with age, season, nutrition, lighting, health, and management, so the production figure is a practical breed range rather than a guarantee.', 'layer', 'blue', '150_200', 'Alert', 2430),
    ('b868735b-0d89-49cb-9e2b-a01b2e9f79fa', 'rosecomb-black-breasted-red', 'Rosecomb - Black Breasted Red', 'Bantams', 'Rosecomb chickens originated in England and were developed during centuries ago. They were preserved as an old true bantam and refined for exhibition around its large rose comb and elegant outline. Their history reflects the practical and cultural priorities of the farmers and breeders who maintained them before modern poultry production narrowed the number of commonly used breeds.

Rosecomb bantams have a compact body, prominent rose comb, white earlobes, and a sweeping tail. FlockFront classifies this profile as Bantams. Hens lay small white eggs, typically under 150 eggs per year. They are generally alert. They are active fliers and often poor brooders; large comb surfaces still need cold-weather protection despite their low profile. Egg output varies with age, season, nutrition, lighting, health, and management, so the production figure is a practical breed range rather than a guarantee.', null, 'white', 'under_150', 'Alert', 2440),
    ('bfd8f838-4bf4-45a9-83f2-64b93efd5a80', 'orloff-gold', 'Orloff Gold', 'Meat Birds', 'Orloff Gold chickens were developed through Whiting Farms in Colorado as a slower-growing meat line related in purpose to Colorado Golds. The line was selected for pasture-oriented meat production with a longer grow-out, giving small farms and direct-market producers an alternative suited to its intended production system. Because commercial breeding programs can change, performance should be understood as a researched range rather than a permanent breed standard.

Orloff Gold are Meat Birds selected for practical carcass production. They are generally active and are typically processed at approximately 11–14 weeks, depending on sex, target weight, feed, and management. Their meat is commonly described as having a rich flavor, tender texture, and practical carcass quality comparable to Colorado Golds. Producers should match feeding, housing, ventilation, and range management to the line''s growth rate and mobility.', 'meat', null, null, 'Active', 2450),
    ('9f6827a3-5a55-44ec-9216-9048e5194ebf', 'colorado-golds', 'Colorado Golds', 'Meat Birds', 'Colorado Golds chickens were developed through Whiting Farms in Colorado as a pasture-oriented colored meat line. The line was selected for outdoor activity and practical carcass quality, giving small farms and direct-market producers an alternative suited to its intended production system. Because commercial breeding programs can change, performance should be understood as a researched range rather than a permanent breed standard.

Colorado Golds are Meat Birds selected for practical carcass production. They are generally active and are typically processed at approximately 9–12 weeks, depending on sex, target weight, feed, and management. Their meat is commonly described as having rich flavor, tenderness, and a balanced meat-to-fat ratio. Producers should match feeding, housing, ventilation, and range management to the line''s growth rate and mobility.', 'meat', null, null, 'Active', 2460);

do $$
declare
  v_species_id uuid;
  v_count integer;
  v_expected_update_count integer;
begin
  select species.id
  into strict v_species_id
  from public.species
  where species.slug = 'chicken';

  select count(*)
  into v_count
  from _chicken_catalog_plan;

  if v_count <> 234 then
    raise exception 'Chicken catalog plan must contain 234 existing records; found %.', v_count;
  end if;

  select count(*)
  into v_count
  from _chicken_catalog_plan as plan
  join public.breeds as breeds
    on breeds.species_id = v_species_id
   and breeds.breed_slug = plan.breed_slug
   and breeds.breed_name = plan.expected_breed_name
   and breeds.is_custom = false;

  v_expected_update_count := v_count;

  if v_expected_update_count not in (228, 234) then
    raise exception 'Existing chicken catalog identity guard failed: expected 228 replayable or 234 production slug/name matches; found %.', v_expected_update_count;
  end if;

  if exists (
    select 1
    from _chicken_catalog_plan as plan
    left join public.breeds as breeds
      on breeds.species_id = v_species_id
     and breeds.breed_slug = plan.breed_slug
     and breeds.breed_name = plan.expected_breed_name
     and breeds.is_custom = false
    where plan.required
      and breeds.id is null
  ) then
    raise exception 'One or more required chicken catalog records are missing or renamed.';
  end if;

  if exists (
    select 1
    from _chicken_catalog_plan as plan
    join public.breeds as breeds
      on breeds.species_id = v_species_id
     and breeds.breed_slug = plan.breed_slug
     and breeds.is_custom = false
    where breeds.breed_name <> plan.expected_breed_name
  ) then
    raise exception 'One or more chicken catalog slugs have an unexpected current name.';
  end if;

  if exists (
    select 1
    from public.breeds as breeds
    join _chicken_catalog_additions as additions
      on additions.breed_slug = breeds.breed_slug
    where breeds.species_id = v_species_id
  ) then
    raise exception 'One or more approved addition slugs already exist for chicken.';
  end if;

  update public.breeds as breeds
  set
    breed_name = plan.target_breed_name,
    is_active = plan.is_active,
    category = case when plan.is_active then plan.category else breeds.category end,
    description = case when plan.is_active then plan.description else breeds.description end,
    bird_type = case when plan.is_active then plan.bird_type else breeds.bird_type end,
    egg_color = case when plan.is_active then plan.egg_color else breeds.egg_color end,
    annual_egg_production = case when plan.is_active then plan.annual_egg_production else breeds.annual_egg_production end,
    temperament = case when plan.is_active then plan.temperament else breeds.temperament end,
    production_traits = case when plan.is_active then null else breeds.production_traits end,
    updated_at = now()
  from _chicken_catalog_plan as plan
  where breeds.species_id = v_species_id
    and breeds.breed_slug = plan.breed_slug
    and breeds.is_custom = false;

  get diagnostics v_count = row_count;
  if v_count <> v_expected_update_count then
    raise exception 'Chicken catalog update expected % records; updated %.', v_expected_update_count, v_count;
  end if;

  insert into public.breeds (
    id, species_id, breed_name, breed_slug, description, category,
    bird_type, egg_color, annual_egg_production, temperament,
    production_traits, is_active, is_custom, sort_order
  )
  select
    additions.id,
    v_species_id,
    additions.breed_name,
    additions.breed_slug,
    additions.description,
    additions.category,
    additions.bird_type,
    additions.egg_color,
    additions.annual_egg_production,
    additions.temperament,
    null,
    true,
    false,
    additions.sort_order
  from _chicken_catalog_additions as additions;

  get diagnostics v_count = row_count;
  if v_count <> 11 then
    raise exception 'Chicken catalog addition expected 11 records; inserted %.', v_count;
  end if;

  select count(*)
  into v_count
  from public.breeds as breeds
  where breeds.species_id = v_species_id
    and breeds.is_custom = false
    and breeds.is_active = true;

  if v_count <> 217 then
    raise exception 'Active default chicken catalog should contain 217 records after curation; found %.', v_count;
  end if;
end;
$$;
